style.css:
body {
  background: linear-gradient(to bottom, #2e0f41, #1a0b28);
  color: #e6d5f7;
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  margin: 0;
  padding: 0;
}

a {
  color: #ff80bf;
  text-decoration: none;
}

a:hover {
  color: #ff4da6;
}

header, footer {
  background-color: #1a0b28;
  padding: 1rem;
  text-align: center;
  box-shadow: 0 4px 6px rgba(0,0,0,0.3);
}

main {
  padding: 2rem;
  background-color: rgba(0, 0, 0, 0.6);
  border-radius: 10px;
  margin: 2rem auto;
  width: 80%;
  color: #f5e6ff;
}

button {
  background-color: #610c5c;
  color: #fff;
  border: none;
  padding: 0.75rem 1.5rem;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.3s ease;
}

button:hover {
  background-color: #a10e85;
}

::selection {
  background: #ff4da6;
  color: #fff;
}
